import json,numpy as np
m=json.load(open('/app/runs/029/meta.json'));print('base',m['proprio']['now'][28:35]);print('eef',m['proprio']['now'][35:49])
for cam in ['robot_r1:left_realsense_link:Camera:0','robot_r1:right_realsense_link:Camera:0']:
 c=m['cameras'][cam];E=np.array(c['extrinsic_cv']);R=E[:3,:3];C=-R.T@E[:3,3];print('\n',cam,'C',C.round(3))
 if 'left_' in cam:
  for name,(u,v),z in [('press',(169,65),1.0),('press center',(170,75),1.05),('counter',(112,70),.95)]:
   ray=R.T@np.array([(u-112)/181.4,(v-112)/181.4,1]);X=C+ray*((z-C[2])/ray[2]);print(name,X.round(3))
