m=json.load(open('/app/runs/044/meta.json'));c=m['cameras']['robot_r1:left_realsense_link:Camera:0'];E=np.array(c['extrinsic_cv']);R=E[:3,:3];C=-R.T@E[:3,3];
for uv,z in [((160,110),1.0),((160,130),1.0),((160,145),.95),((150,105),1.05),((170,115),1.05),((150,145),.95)]:
